import XCTest
import CryptoKit
@testable import PyroChat

/// Desktop-link crypto + QR parsing. The golden vectors were generated by an
/// independent node:crypto implementation of docs/MIRROR-PROTOCOL.md and are
/// also asserted against the web client's JS — all three implementations must
/// agree byte-for-byte.
final class MirrorTests: XCTestCase {
    static let relay = URL(string: "ws://72.62.171.10:7443/ws")!

    // MARK: - QR parsing

    func testParseAcceptsDifferentPortSameHost() throws {
        // web TLS listener on :7444, phone relay on :7443 — same operator
        let pub = MirrorCrypto.b64url(Data(repeating: 7, count: 32))
        let link = try MirrorLink.parse(
            "pyro-link:v1:TESTPAIRID0000000000AA:\(pub):72.62.171.10:7444",
            expectedRelay: Self.relay)
        XCTAssertEqual(link.host, "72.62.171.10:7444")
    }

    func testParseValidPayload() throws {
        let pub = Data(repeating: 0x22, count: 32)
        let raw = "pyro-link:v1:TESTPAIRID0000000000AA:\(MirrorCrypto.b64url(pub)):72.62.171.10:7443"
        let link = try MirrorLink.parse(raw, expectedRelay: Self.relay)
        XCTAssertEqual(link.pairId, "TESTPAIRID0000000000AA")
        XCTAssertEqual(link.browserPub, pub)
        XCTAssertEqual(link.host, "72.62.171.10:7443")
    }

    func testParseRejectsNonPyroPayloadSilently() {
        XCTAssertThrowsError(try MirrorLink.parse("https://example.com", expectedRelay: Self.relay)) {
            XCTAssertEqual($0 as? MirrorLink.ParseError, .notPyroLink)
        }
    }

    func testParseRejectsWrongVersionAndBadPair() {
        let pub = MirrorCrypto.b64url(Data(repeating: 1, count: 32))
        XCTAssertThrowsError(try MirrorLink.parse(
            "pyro-link:v2:TESTPAIRID0000000000AA:\(pub):h", expectedRelay: Self.relay)) {
            XCTAssertEqual($0 as? MirrorLink.ParseError, .malformed)
        }
        XCTAssertThrowsError(try MirrorLink.parse(
            "pyro-link:v1:short:\(pub):h", expectedRelay: Self.relay)) {
            XCTAssertEqual($0 as? MirrorLink.ParseError, .malformed)
        }
        XCTAssertThrowsError(try MirrorLink.parse(
            "pyro-link:v1:TESTPAIRID0000000000AA:notakey:h", expectedRelay: Self.relay)) {
            XCTAssertEqual($0 as? MirrorLink.ParseError, .malformed)
        }
    }

    func testParseRejectsWrongRelayNamingBothHosts() {
        let pub = MirrorCrypto.b64url(Data(repeating: 1, count: 32))
        XCTAssertThrowsError(try MirrorLink.parse(
            "pyro-link:v1:TESTPAIRID0000000000AA:\(pub):evil.example:9999",
            expectedRelay: Self.relay)) {
            XCTAssertEqual($0 as? MirrorLink.ParseError,
                           .wrongRelay(expected: "72.62.171.10", got: "evil.example"))
        }
    }

    // MARK: - KDF golden vector (independent node:crypto implementation)

    /// phoneSeed = 32×0x31, browserSeed = 32×0x32, pairId TESTPAIRID0000000000AA
    func testKdfGoldenVector() throws {
        let phonePriv = try Curve25519.KeyAgreement.PrivateKey(
            rawRepresentation: Data(repeating: 0x31, count: 32))
        let browserPriv = try Curve25519.KeyAgreement.PrivateKey(
            rawRepresentation: Data(repeating: 0x32, count: 32))
        let pPub = phonePriv.publicKey.rawRepresentation
        let bPub = browserPriv.publicKey.rawRepresentation
        XCTAssertEqual(pPub.base64EncodedString(), "BPXykWLDGo3voY5udCIk7oBvwXGKJ4voWbpWIEArjzo=")
        XCTAssertEqual(bPub.base64EncodedString(), "WdkiVHNFHv/+azbbyu/b97GJXeYghFCaf1tYvwHQZBg=")

        let ss = try phonePriv.sharedSecretFromKeyAgreement(with: browserPriv.publicKey)
        let keys = MirrorCrypto.deriveKeys(sharedSecret: ss, pairId: "TESTPAIRID0000000000AA",
                                           phonePub: pPub, browserPub: bPub)
        XCTAssertEqual(keys.sas, "114703")

        // the exact record node:crypto sealed with k_p2b must open here
        let rec = Data(base64Encoded: "AwAAAAAAAAABUd93pG05sCrHg2n4I7rP4/wSceC3fdplPrLRczueeRn7ms6/MTI=")!
        XCTAssertEqual(rec[0], 0x03)
        let seq = rec.subdata(in: 1..<9).reduce(UInt64(0)) { ($0 << 8) | UInt64($1) }
        XCTAssertEqual(seq, 1)
        let pt = try MirrorCrypto.open(key: keys.p2b, dir: "p2b",
                                       pairId: "TESTPAIRID0000000000AA",
                                       type: 0x03, seq: 1, sealed: rec.subdata(in: 9..<rec.count))
        XCTAssertEqual(String(data: pt, encoding: .utf8), #"{"e":"conn","up":true}"#)

        // and sealing the same plaintext reproduces it byte-for-byte
        let sealed = try MirrorCrypto.seal(key: keys.p2b, dir: "p2b",
                                           pairId: "TESTPAIRID0000000000AA",
                                           type: 0x03, seq: 1,
                                           plaintext: Data(#"{"e":"conn","up":true}"#.utf8))
        XCTAssertEqual(sealed, rec)
    }

    // MARK: - record integrity

    func testTamperedRecordRejected() throws {
        let a = Curve25519.KeyAgreement.PrivateKey()
        let b = Curve25519.KeyAgreement.PrivateKey()
        let ss = try a.sharedSecretFromKeyAgreement(with: b.publicKey)
        let keys = MirrorCrypto.deriveKeys(sharedSecret: ss, pairId: "TESTPAIRID0000000000AA",
                                           phonePub: a.publicKey.rawRepresentation,
                                           browserPub: b.publicKey.rawRepresentation)
        let rec = try MirrorCrypto.seal(key: keys.p2b, dir: "p2b",
                                        pairId: "TESTPAIRID0000000000AA",
                                        type: 0x03, seq: 5, plaintext: Data("hi".utf8))
        var sealed = rec.subdata(in: 9..<rec.count)

        // flip one ciphertext bit
        sealed[0] ^= 1
        XCTAssertThrowsError(try MirrorCrypto.open(key: keys.p2b, dir: "p2b",
            pairId: "TESTPAIRID0000000000AA", type: 0x03, seq: 5, sealed: sealed))
        sealed[0] ^= 1

        // replay under a different seq must fail (nonce+AAD bind the position)
        XCTAssertThrowsError(try MirrorCrypto.open(key: keys.p2b, dir: "p2b",
            pairId: "TESTPAIRID0000000000AA", type: 0x03, seq: 6, sealed: sealed))
        // wrong direction key/nonce must fail
        XCTAssertThrowsError(try MirrorCrypto.open(key: keys.b2p, dir: "b2p",
            pairId: "TESTPAIRID0000000000AA", type: 0x03, seq: 5, sealed: sealed))
        // wrong type in AAD must fail
        XCTAssertThrowsError(try MirrorCrypto.open(key: keys.p2b, dir: "p2b",
            pairId: "TESTPAIRID0000000000AA", type: 0x02, seq: 5, sealed: sealed))
        // intact original still opens
        XCTAssertNoThrow(try MirrorCrypto.open(key: keys.p2b, dir: "p2b",
            pairId: "TESTPAIRID0000000000AA", type: 0x03, seq: 5, sealed: sealed))
    }

    @MainActor
    func testBrowserNameSanitizer() {
        XCTAssertEqual(MirrorEngine.sanitizeBrowserName("Chrome on Mac"), "Chrome on Mac")
        XCTAssertEqual(MirrorEngine.sanitizeBrowserName("<script>alert(1)</script>"),
                       "scriptalert1script")
        XCTAssertEqual(MirrorEngine.sanitizeBrowserName("  Firefox on Windows  "),
                       "Firefox on Windows")
        XCTAssertNil(MirrorEngine.sanitizeBrowserName("!!!"))
        XCTAssertEqual(MirrorEngine.sanitizeBrowserName(String(repeating: "A", count: 99))?.count, 32)
    }

    func testB64urlRoundtrip() {
        for n in [0, 1, 2, 3, 31, 32, 33] {
            let d = Data((0..<n).map { UInt8(($0 &* 37) & 0xff) })
            let s = MirrorCrypto.b64url(d)
            XCTAssertFalse(s.contains("+") || s.contains("/") || s.contains("="))
            XCTAssertEqual(Data(base64urlNoPad: s), d)
        }
    }
}
